def _helper_prelude() -> str:
    """Definitions for Ghidra's size-encoded arithmetic intrinsics."""
    lines: list[str] = []
    concats = (
        (7, 1), (4, 4), (3, 1), (1, 1), (2, 2), (1, 2), (2, 8),
        (1, 3), (6, 2), (1, 7), (2, 1), (1, 6), (2, 6), (1, 5),
        (1, 4), (2, 4), (8, 8), (6, 4), (5, 3), (3, 4), (4, 3),
    )
    for high, low in concats:
        total = high + low
        lines.append(
            f"#define CONCAT{high}{low}(a,b) "
            f"((uint{total})(((uint{total})(a) << {low * 8}) | (uint{low})(b)))"
        )
    subs = ((16, 8), (16, 12), (10, 8), (8, 1), (8, 4), (2, 1),
            (16, 1), (4, 1), (16, 14), (8, 6), (10, 4), (8, 5))
    for source, result in subs:
        lines.append(
            f"#define SUB{source}{result}(v,o) "
            f"((uint{result})((uint{source})(v) >> ((unsigned)(o) * 8)))"
        )
    for source, result in ((8, 16), (4, 16), (1, 16), (4, 12)):
        lines.append(f"#define ZEXT{source}{result}(v) ((uint{result})(uint{source})(v))")
    lines.extend((
        "static inline vec64 _gh_zext1664(uint16 v) { union { vec64 o; uint16 i; } u = {0}; u.i = v; return u.o; }",
        "static inline vec64 _gh_zext3264(vec32 v) { union { vec64 o; vec32 i[2]; } u = {0}; u.i[0] = v; return u.o; }",
        "static inline vec32 _gh_sub6432(vec64 v, unsigned o) { union { vec64 i; vec32 o[2]; } u; u.i = v; return u.o[o / 32]; }",
        "#define ZEXT1664(v) _gh_zext1664((v))",
        "#define ZEXT3264(v) _gh_zext3264((v))",
        "#define SUB6432(v,o) _gh_sub6432((v),(o))",
    ))
    lines.append("#define SEXT816(v) ((int16)(int8)(v))")
    for width in (1, 4, 8):
        lines.append(
            f"#define CARRY{width}(a,b) "
            f"((uint{width})((uint{width})(a) + (uint{width})(b)) < (uint{width})(a))"
        )
        lines.append(
            f"#define SCARRY{width}(a,b) "
            f"({{ int{width} _r; __builtin_add_overflow((int{width})(a),(int{width})(b),&_r); }})"
        )
        lines.append(
            f"#define SBORROW{width}(a,b) "
            f"({{ int{width} _r; __builtin_sub_overflow((int{width})(a),(int{width})(b),&_r); }})"
        )
    return "\n".join(lines) + "\n"


