_SIG_CACHE: dict[object, tuple[tuple[str, str], ...]] = {}


def _signature(name: str, code: str) -> str | None:
    """Return Ghidra's leading function declarator as a prototype."""
    brace = code.find("{")
    if brace < 0:
        return None
    head = code[:brace].strip()
    head = re.sub(r"/\*.*?\*/", "", head, flags=re.S).strip()
    head = re.sub(r"\bundefined1\s*\[\s*16\s*\](\s*" + re.escape(name) + r"\b)", r"unsigned __int128\1", head)
    head = re.sub(r"\bundefined1\s*\[\s*32\s*\](\s*" + re.escape(name) + r"\b)", r"vec32\1", head)
    if not head or ")" not in head:
        return None
    match = re.search(r"\b" + re.escape(name) + r"\s*\(", head)
    if not match:
        return None
    # Ghidra often assigns fixed dummy parameters to genuinely variadic
    # routines and may infer inconsistent signatures at different call sites.
    # An old-style declaration retains the inferred return type/width while
    # leaving the call-site ABI decisions to the actual argument expressions.
    prefix = head[:match.start()]
    if prefix.strip() == "void":
        prefix = "long "
    return "extern " + prefix + name + "();"


def _sibling_signatures(ctx) -> tuple[tuple[str, str], ...]:
    key = ctx.binary_key
    cached = _SIG_CACHE.get(key)
    if cached is not None:
        return cached
    out: list[tuple[str, str]] = []
    try:
        for name, body in ctx.siblings.items():
            sig = _signature(name, body)
            if sig:
                out.append((name, sig))
    except Exception:
        pass
    result = tuple(out)
    if len(_SIG_CACHE) > 128:
        _SIG_CACHE.clear()
    _SIG_CACHE[key] = result
    return result


_TAG_TYPES = ("stat", "stat64", "sigaction", "statfs", "statvfs")


def _rewrite_dialect(code: str) -> str:
    """Translate Ghidra constructs which have no direct C spelling."""
    # Auto-generated data labels occasionally contain punctuation copied from
    # a string preview. Such labels are symbols, not string literals.
    def clean_label(match: re.Match[str]) -> str:
        return re.sub(r"\W", "_", match.group(0))

    code = re.sub(
        r"\b(?:PTR_s|s)_[^\s;,]+?_[0-9A-Fa-f]{6,}", clean_label, code
    )
    code = re.sub(r"\b(?:PTR|DAT|FUN|LAB|UNK)_[A-Za-z0-9_$<>.@?-]+", clean_label, code)

    # Ghidra prints a namespace-like owner for switch-table data labels. C has
    # no `::` operator; the right-hand label is the actual referenced object.
    code = re.sub(r"\b[A-Za-z_]\w*::([A-Za-z_]\w*)", r"\1", code)

    # Generated anonymous union names are local type artifacts. Their uses in
    # this dialect are word-sized bit containers.
    anon_unions = sorted(set(re.findall(r"\b_union_\d+\b", code)) - {"_union_1457"})
    if anon_unions:
        code = "\n".join("typedef unsigned long " + name + ";" for name in anon_unions) + "\n" + code

    code = re.sub(r"\bundefined1\s*\[\s*16\s*\](\s+[A-Za-z_]\w*\s*\()", r"unsigned __int128\1", code)
    code = re.sub(r"\bundefined1\s*\[\s*32\s*\](\s+[A-Za-z_]\w*\s*\()", r"vec32\1", code)
    code = re.sub(r"\(\s*timespec\s*\)\s*(?=[A-Za-z_]\w*\s*\()", "", code)
    code = re.sub(r"\*(stdin|stdout|stderr)\s*&", r"\1->_flags &", code)

    for typename in _TAG_TYPES:
        # Casts and ordinary declarations. Keeping the tag separate permits a
        # function with the same name, as libc does for stat and sigaction.
        code = re.sub(r"\(\s*" + typename + r"\s*\*", "(struct " + typename + " *", code)
        code = re.sub(
            r"(?<!struct )\b" + typename + r"\s+(\*+\s*)?([A-Za-z_]\w*)",
            lambda m, t=typename: "struct " + t + " " + (m.group(1) or "") + m.group(2),
            code,
        )

    # A 16-byte undefined array with synthetic fields is Ghidra's spelling of
    # a 128-bit temporary. Give arithmetic on it the matching scalar type.
    vector_names = set(re.findall(r"(?<!\.)\b([A-Za-z_]\w*)\._\d+_\d+_", code))
    array16_names = set(re.findall(r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*16\s*\]", code))
    for name in array16_names:
        q = re.escape(name)
        if not re.search(r"\b" + q + r"\s*=(?!=)", code):
            continue
        without_decl = re.sub(
            r"\bundefined1\s+" + q + r"\s*\[\s*16\s*\]", "", code
        )
        buffer_use = (re.search(r"\b" + q + r"\s*\[", without_decl) or
                      re.search(r"\([^)]*\*\s*\)\s*" + q + r"\b", without_decl) or
                      re.search(r"\b(?:str\w*|mem\w*|snprintf|read|write)\s*\([^;\n]*\b" + q + r"\b", without_decl))
        if not buffer_use:
            vector_names.add(name)
    for name in array16_names - vector_names:
        q = re.escape(name)
        code = re.sub(
            r"\b" + q + r"\s*=(?!=)\s*([^;]+);",
            lambda m, n=name: "*(uint16 *)" + n + " = (uint16)(" + m.group(1) + ");",
            code,
        )
    pointer16_names = set(re.findall(
        r"\bundefined1\s*\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\[\s*16\s*\]", code
    ))
    code = re.sub(
        r"\bundefined1\s*\(\s*\*\s*([A-Za-z_]\w*)\s*\)\s*\[\s*16\s*\]",
        r"unsigned __int128 *\1",
        code,
    )
    for name in pointer16_names:
        q = re.escape(name)
        code = re.sub(
            r"\b" + q + r"\s*\[([^\]]+)\]\s*\[([^\]]+)\]",
            r"((undefined1 *)&" + name + r"[\1])[\2]", code,
        )
        code = re.sub(
            r"\(\s*\*\s*" + q + r"\s*\)\s*\[([^\]]+)\]",
            r"((undefined1 *)" + name + r")[\1]", code,
        )
    if vector_names:
        code = re.sub(
            r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*16\s*\]",
            lambda m: ("unsigned __int128 " + m.group(1)) if m.group(1) in vector_names else m.group(0),
            code,
        )
        for name in vector_names:
            code = re.sub(
                r"(?<!undefined1 )(?<!\.)\b" + re.escape(name) + r"\s*\[([^\]]+)\]",
                r"((undefined1 *)&" + name + r")[\1]",
                code,
            )
    code = re.sub(
        r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*(\d+)\s*\]\s*\[\s*16\s*\]",
        r"unsigned __int128 \1[\2]", code,
    )
    for width in (8, 12):
        names = set(re.findall(
            r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*" + str(width) + r"\s*\]", code
        ))
        for name in names:
            if re.search(r"\b" + re.escape(name) + r"\s*=(?!=)", code):
                code = re.sub(
                    r"\bundefined1\s+" + re.escape(name) + r"\s*\[\s*" + str(width) + r"\s*\]",
                    "uint" + str(width) + " " + name, code,
                )
    vector32_names: set[str] = set()
    for name in re.findall(r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*32\s*\]", code):
        if re.search(r"\b" + re.escape(name) + r"\s*=", code) or re.search(r"\b" + re.escape(name) + r"\._", code):
            vector32_names.add(name)
    if vector32_names:
        code = re.sub(
            r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*32\s*\]",
            lambda m: ("vec32 " + m.group(1)) if m.group(1) in vector32_names else m.group(0),
            code,
        )
    vector64_names: set[str] = set()
    for name in re.findall(r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*64\s*\]", code):
        if re.search(r"\b" + re.escape(name) + r"\s*=(?!=)", code) or re.search(r"\b" + re.escape(name) + r"\._", code):
            vector64_names.add(name)
    if vector64_names:
        code = re.sub(
            r"\bundefined1\s+([A-Za-z_]\w*)\s*\[\s*64\s*\]",
            lambda m: ("vec64 " + m.group(1)) if m.group(1) in vector64_names else m.group(0),
            code,
        )

    # Synthetic fields encode a byte offset and width. A pointer-based lvalue
    # preserves both reads and assignments without inventing a struct layout.
    code = re.sub(
        r"\b([A-Za-z_]\w*(?:(?:\s*\[[^\]]+\])|(?:\.[A-Za-z_]\w*))*)\._(\d+)_(\d+)_",
        lambda m: "(*(uint" + m.group(3) + " *)((char *)&" + m.group(1) + " + " + m.group(2) + "))",
        code,
    )
    code = re.sub(
        r"\b([A-Za-z_]\w*)\.sa_data\s*=\s*([^;]+);",
        r"(*(uint14 *)&\1.sa_data) = \2;",
        code,
    )
    code = re.sub(r"\(\s*undefined1\s*\[\s*16\s*\]\s*\)", "(unsigned __int128)", code)
    code = re.sub(r"undefined1\s*\(\s*\*\s*\)\s*\[\s*16\s*\]", "unsigned __int128 *", code)
    code = re.sub(r"undefined1\s*\(\s*\*\s*\)\s*\[\s*32\s*\]", "vec32 *", code)
    code = re.sub(r"\(\s*undefined1\s*\[\s*32\s*\]\s*\)", "(vec32)", code)
    code = re.sub(
        r"\(vec32 \*\)\(\*\(vec32 \*\)([A-Za-z_]\w*)\s*\+\s*([A-Za-z_]\w*)\)",
        r"(vec32 *)((unsigned char *)\1 + \2)",
        code,
    )
    for name in set(re.findall(r"\bchar\s+([A-Za-z_]\w*)\s*\[\s*8\s*\]", code)):
        code = re.sub(
            r"\b" + re.escape(name) + r"\s*=\s*\(\s*char\s*\[\s*8\s*\]\s*\)\s*([^;]+);",
            lambda m, n=name: "*(uint8 *)" + n + " = (uint8)(" + m.group(1) + ");",
            code,
        )
    # Ghidra gives the signal-handler union an anonymous generated name. Keep
    # its word representation while exposing the named pointer member.
    code = re.sub(
        r"(?<![.\w])([A-Za-z_]\w*(?:\s*\[[^\]]+\])?)\.sa_handler\b",
        r"(*(__sighandler_t *)&\1)",
        code,
    )
    code = re.sub(
        r"\b([A-Za-z_]\w*)\s*->\s*sa_handler\b",
        r"(*(__sighandler_t *)\1)",
        code,
    )
    # A wide synthetic field immediately dereferenced is itself a recovered
    # pointer value, rather than an integer object to dereference in C.
    code = re.sub(
        r"\*\(\*\(uint8 \*\)\(\(char \*\)&([^;\n]+?)\)\)",
        r"*(int *)(*(uint8 *)((char *)&\1))",
        code,
    )

    # Occasionally Ghidra's data-flow merge leaves a pointer-valued local with
    # an integer placeholder type. A unary dereference proves its shape.
    scalar_decl = re.compile(r"\b(undefined8|undefined4|ulong|uint|long|int)\s+([A-Za-z_]\w*)\s*;")
    original = code

    def pointer_local(match: re.Match[str]) -> str:
        typename, name = match.group(1), match.group(2)
        q = re.escape(name)
        unary = re.search(r"(?:^|[([=,!?:;{}])\s*\*\s*" + q + r"\b", original, re.M)
        cast_unary = re.search(r"\([A-Za-z_][A-Za-z0-9_\s*]*\)\s*\*\s*" + q + r"\b", original)
        if unary or cast_unary:
            return typename + " *" + name + ";"
        return match.group(0)

    code = scalar_decl.sub(pointer_local, code)
    return code


def _inferred_callee_declarations(code: str, excluded: set[str] | None = None) -> list[str]:
    """Infer ABI-significant returns for anonymous Ghidra callees."""
    inferred: dict[str, str] = {}
    excluded = excluded or set()
    helper_prefixes = ("CONCAT", "SUB", "ZEXT", "SEXT", "CARRY", "SCARRY", "SBORROW")

    # An explicit cast at a call site is strong evidence that the full pointer
    # in RAX is significant; implicit int would otherwise truncate it.
    for match in re.finditer(
        r"\(\s*([A-Za-z_]\w*(?:\s+[A-Za-z_]\w*)?\s*\*+)\s*\)\s*([A-Za-z_]\w*)\s*\(",
        code,
    ):
        if match.group(2) not in excluded and not match.group(2).startswith(helper_prefixes):
            inferred[match.group(2)] = "void *"

    # Ghidra also commonly omits a redundant cast when assigning to a typed
    # local. Preserve floating-point and machine-word return conventions.
    variable_types: dict[str, str] = {}
    for match in re.finditer(
        r"(?m)^\s*(undefined8|ulong|long|size_t|ssize_t|time_t|double|float|longdouble|timespec|vec32|uint8|uint12|uint16)\s+([A-Za-z_]\w*)\s*;",
        code,
    ):
        variable_types[match.group(2)] = match.group(1)
    for match in re.finditer(r"\b([A-Za-z_]\w*)\s*=\s*([A-Za-z_]\w*)\s*\(", code):
        vartype = variable_types.get(match.group(1))
        if (vartype and match.group(2) not in inferred and match.group(2) not in excluded and
                not match.group(2).startswith(helper_prefixes)):
            inferred[match.group(2)] = vartype

    # A routine used both as a callback value and as a direct call needs a
    # declaration before its first bare use.
    for name in set(re.findall(r"\b([A-Za-z_]\w*)\s*\(", code)) - excluded:
        if (name not in inferred and name not in _C_WORDS and name not in _KNOWN_TYPES and
                not name.startswith(helper_prefixes) and
                re.search(r"\b" + re.escape(name) + r"\b(?!\s*\()", code)):
            inferred[name] = "long"

    return [f"extern {rettype} {name}();" for name, rettype in inferred.items()]


_C_WORDS = {
    "auto", "break", "case", "char", "const", "continue", "default", "do",
    "double", "else", "enum", "extern", "float", "for", "goto", "if",
    "inline", "int", "long", "register", "restrict", "return", "short",
    "signed", "sizeof", "static", "struct", "switch", "typedef", "union",
    "unsigned", "void", "volatile", "while", "_Bool", "_Complex", "true",
    "false", "NULL",
}
_KNOWN_TYPES = {
    "undefined", "undefined1", "undefined2", "undefined3", "undefined4",
    "undefined5", "undefined6", "undefined7", "undefined8", "byte", "uchar",
    "sbyte", "ushort", "uint", "ulong", "longlong", "ulonglong", "longdouble",
    "size_t", "ssize_t", "wchar_t", "wint_t", "time_t", "FILE", "DIR",
    "mbstate_t", "sigset_t", "fd_set", "stat", "stat64", "timespec", "timeval",
    "tm", "passwd", "group", "rusage", "rlimit", "dirent", "termios",
    "sigaction", "sockaddr", "addrinfo", "servent", "pollfd", "utsname",
    "lconv", "regex_t", "re_pattern_buffer", "pthread_t", "pthread_mutex_t",
    "pthread_mutexattr_t", "pthread_cond_t", "pthread_condattr_t", "iovec",
    "statfs", "statvfs", "code", "vec32", "vec64", "imaxdiv_t", "locale_t", "bool",
    "__pid_t", "__uid_t", "__gid_t", "__mode_t", "__off_t", "__off64_t",
    "__ssize_t", "__sighandler_t", "__jmp_buf_tag", "cpu_set_t", "socklen_t",
    "__timezone_ptr_t", "__dev_t", "__time_t", "__fd_mask", "__blksize_t",
    "__ino_t", "__nlink_t", "_union_1457", "_IO_FILE", "speed_t", "rlim_t",
    "timer_t", "itimerval", "msghdr", "__gnuc_va_list", "__suseconds_t",
    "iconv_t", "cc_t", "unkbyte10",
    "__int128", "__int32_t", "__sigset_t", "utimbuf", "timezone", "tms",
    "uint16_t", "uint32_t", "uint64_t", "uintmax_t", "intmax_t", "va_list",
    "regmatch_t", "re_registers", "__nlink_t", "dirent64", "uint32", "uint64",
    "wctype_t", "__blkcnt_t", "unkuint10", "reg_syntax_t", "regoff_t",
    "__rlimit_resource_t", "in_addr_t", "pthread_attr_t", "itimerspec", "sigevent",
    "__compar_fn_t", "MD5_CTX",
    "_IO_marker", "__cmp", "BADSPACEBASE",
} | {f"int{i}" for i in range(1, 17)} | {f"uint{i}" for i in range(1, 17)}
_PREDECLARED = {"stdin", "stdout", "stderr", "errno", "optind", "opterr", "optopt", "optarg", "environ"}


def _inferred_global_declarations(code: str, ctx) -> list[str]:
    """Find identifiers Ghidra references without emitting storage for them."""
    # Hide comments and literals while keeping character positions stable
    # enough for neighboring-token tests.
    clean = re.sub(r"/\*.*?\*/|//[^\n]*|\"(?:\\.|[^\"\\])*\"|'(?:\\.|[^'\\])*'",
                   lambda m: " " * len(m.group(0)), code, flags=re.S)
    local: set[str] = set(re.findall(
        r"\b(?:param_\w+|local_\w+|[A-Za-z]*Var\d+|[A-Za-z]+Stack_[A-Za-z0-9_]+|"
        r"in_[A-Z]+_OFFSET|unaff_[A-Za-z0-9_]+|extraout_[A-Za-z0-9_]+|stack0x[A-Fa-f0-9]+)\b",
        clean,
    ))
    # Capture conventional declarations such as `char *__s;` and arrays.
    for line in clean.splitlines():
        match = re.match(
            r"\s*(?:const\s+|volatile\s+|struct\s+|union\s+)*[A-Za-z_]\w*"
            r"(?:\s+[A-Za-z_]\w*)?\s+(.+);\s*$",
            line,
        )
        if match and not re.search(r"[+/%|!?]", match.group(1)):
            for part in match.group(1).split(","):
                names = re.findall(r"[A-Za-z_]\w*", part)
                if names:
                    local.add(names[-1])

    calls = set(re.findall(r"\b([A-Za-z_]\w*)\s*\(", clean))
    assigned_names = set(re.findall(r"\b([A-Za-z_]\w*)\s*=(?!=)", clean))
    labels = set(re.findall(r"(?m)^\s*([A-Za-z_]\w*)\s*:", clean))
    members = set(re.findall(r"(?:\.|->)\s*([A-Za-z_]\w*)", clean))
    dynamic_types = set(re.findall(r"\b_union_\d+\b", clean))
    dynamic_types.update(re.findall(r"\btypedef\s+[^;\n]*\b([A-Za-z_]\w*)\s*;", clean))
    try:
        sibling_names = set(ctx.siblings)
    except Exception:
        sibling_names = set()
    skip = (_C_WORDS | _KNOWN_TYPES | dynamic_types | _PREDECLARED | local | (calls - assigned_names) | labels | members |
            set(_LIBRARY_DECLS) | (sibling_names - assigned_names) | {getattr(ctx, "func_name", "")})

    candidates: list[str] = []
    for name in re.findall(r"\b[A-Za-z_]\w*\b", clean):
        if name in skip or name.startswith(("CONCAT", "SUB", "ZEXT", "SEXT", "CARRY", "SCARRY", "SBORROW")):
            continue
        # A token directly following `struct`, `union`, or `enum` is a tag.
        if re.search(r"\b(?:struct|union|enum)\s+" + re.escape(name) + r"\b", clean):
            continue
        if name not in candidates:
            candidates.append(name)
    # Declaration-line recovery is deliberately conservative. Ensure that a
    # directly dereferenced data label is never lost to that heuristic.
    direct_deref = set(re.findall(
        r"(?:^|[([=,!?:;{}+\-/])\s*\*\s*(DAT_[A-Za-z0-9_]+)\b", clean, re.M
    ))
    direct_deref.update(re.findall(
        r"\(\s*(?:int|uint|long|ulong|char|byte|undefined\d*)\s*\)\s*\*\s*(DAT_[A-Za-z0-9_]+)\b",
        clean,
    ))
    direct_deref -= set(re.findall(r"\(\s*\*\s*(DAT_[A-Za-z0-9_]+)\s*\)\s*\(", clean))
    declared_names = set(re.findall(
        r"(?m)^\s*[A-Za-z_]\w*(?:\s+[A-Za-z_]\w*)?\s+\*?\s*([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*;",
        clean,
    ))
    for name in re.findall(r"\b([A-Za-z_]\w*)\s*\[", clean):
        if (name not in candidates and name not in declared_names and name not in _PREDECLARED and
                not re.match(r"(?:param_|local_|[A-Za-z]*Var\d+|[A-Za-z]+Stack_)", name)):
            candidates.append(name)
    for name in assigned_names:
        if (name not in candidates and name not in local and name not in members and
                name not in _PREDECLARED and name != getattr(ctx, "func_name", "") and
                not re.match(r"(?:param_|local_|[A-Za-z]*Var\d+|[A-Za-z]+Stack_)", name)):
            candidates.append(name)
    pointer_locals = re.findall(
        r"(?m)^\s*(?:const\s+)?[A-Za-z_]\w*(?:\s+[A-Za-z_]\w*)?\s*\*+\s*([A-Za-z_]\w*)\s*;",
        code,
    )
    return [_global_declaration(name, code, pointer_locals=pointer_locals)
            for name in candidates if name not in direct_deref]


def _relax_recursive_signature(code: str, target: str) -> str:
    """Use equivalent GNU old-style syntax when Ghidra omits recursive args."""
    if len(re.findall(r"\b" + re.escape(target) + r"\s*\(", code)) < 2:
        return code
    header = re.search(
        r"\b" + re.escape(target) + r"\s*\(([^()]*)\)\s*\n\s*\{",
        code,
    )
    if not header or not header.group(1).strip():
        return code
    params = [part.strip() for part in header.group(1).split(",")]
    names: list[str] = []
    for param in params:
        match = re.search(r"([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*$", param)
        if not match:
            return code
        names.append(match.group(1))
    replacement = target + "(" + ",".join(names) + ")\n" + ";\n".join(params) + ";\n{"
    return code[:header.start()] + replacement + code[header.end():]


def prepare(code: str, ctx) -> str:
    code = _rewrite_dialect(code)
    declarations: list[str] = []
    try:
        target = ctx.func_name
        # A recursive call consumed as a pointer value is stronger return-type
        # evidence than a decompiler's occasional `void` placeholder.
        if re.search(r"=\s*\([^;()]*\*\)\s*" + re.escape(target) + r"\s*\(", code):
            code = re.sub(
                r"\A(\s*(?:typedef[^\n]+\n)*)void(\s+" + re.escape(target) + r"\s*\()",
                r"\1void *\2", code, count=1,
            )
        code = _relax_recursive_signature(code, target)
        excluded_callees = set(_LIBRARY_DECLS)
        try:
            excluded_callees.update(ctx.siblings)
        except Exception:
            pass
        excluded_callees.add(target)
        for name, sig in _sibling_signatures(ctx):
            if (name != target and name not in _LIBRARY_DECLS and
                    re.search(r"\b" + re.escape(name) + r"\b", code) and
                    not re.search(r"\b" + re.escape(name) + r"\s*=(?!=)", code)):
                declarations.append(sig)
        for name, decl in _LIBRARY_DECLS.items():
            if name != target and re.search(r"\b" + name + r"\s*\(", code):
                declarations.append(decl)
        declarations.extend(_inferred_callee_declarations(code, excluded_callees))
        for name in dict.fromkeys(re.findall(
            r"(?:^|[([=,!?:;{}+\-/])\s*\*\s*(DAT_[A-Za-z0-9_]+)\b", code, re.M
        ) + re.findall(
            r"\(\s*(?:int|uint|long|ulong|char|byte|undefined\d*)\s*\)\s*\*\s*(DAT_[A-Za-z0-9_]+)\b",
            code,
        )):
            if not re.search(r"\(\s*\*\s*" + re.escape(name) + r"\s*\)\s*\(", code):
                declarations.append(f"extern int *{name};")
        declarations.extend(_inferred_global_declarations(code, ctx))
    except Exception:
        declarations = []
    return _PRELUDE + "\n" + _HELPER_PRELUDE + "\n".join(declarations) + "\n\n" + code


_UNDECLARED_RE = re.compile(r"error: ['\u2018]([A-Za-z_]\w*)['\u2019] undeclared")


def _global_declaration(
    name: str, source: str, evidence: str | None = None,
    pointer_locals: list[str] | None = None,
) -> str:
    """Infer a conservative storage shape from uses of an undeclared name."""
    q = re.escape(name)
    observed = evidence or source
    assigned = re.search(r"\b" + q + r"\s*=(?!=)", observed)
    if re.search(r"\b" + q + r"\s*=\s*\(\s*code\s*\*\s*\)", observed):
        return f"extern long (*{name})();"
    if assigned and re.search(r"\(\s*\*\s*" + q + r"\s*\)\s*\(", source):
        return f"extern long (*{name})();"
    if assigned and re.search(r"\b" + q + r"\s*\[", source):
        cast = re.search(r"\b" + q + r"\s*=\s*\(([^()]*)\*\)", observed)
        if cast and re.search(r"(?:char|byte|undefined1)\b", cast.group(1)):
            return f"extern unsigned char *{name};"
        return f"extern unsigned long *{name};"
    if re.search(r"\b" + q + r"\s*\[", source):
        if (not name.startswith("DAT_") and
                re.search(r"\b" + q + r"\s*\+", source)):
            if re.search(r"\b" + q + r"\s*\[[^\]]+\]\s*=\s*\([^)]*\*\)", source):
                return f"extern unsigned long *{name};"
            return f"extern unsigned char *{name};"
        return f"extern unsigned char {name}[];"
    if re.search(r"\(\s*(?:int|uint|undefined4)\s*\)\s*\b" + q + r"\b", observed):
        return f"extern int {name};"
    # Assignment to a known scalar local is direct width evidence and avoids
    # mistaking a nearby multiplication or cast for a pointer dereference.
    scalar_locals = re.findall(
        r"(?m)^\s*(?:int|uint|undefined4|char|byte)\s+([A-Za-z_]\w*)\s*;",
        observed,
    )
    if any(re.search(r"\b" + re.escape(local) + r"\s*=\s*" + q + r"\b", observed)
           for local in scalar_locals):
        return f"extern int {name};"
    if re.search(r"\(\s*long\s*\)[A-Za-z_]\w*\s*-\s*\b" + q + r"\b", observed):
        return f"extern long {name};"
    if name.startswith("FUN_") or re.search(r"\(\s*\*\s*" + q + r"\s*\)\s*\(", source):
        return f"extern long {name}();"
    if name.startswith("PTR_") or re.search(r"\b" + q + r"\s*->", observed):
        return f"extern unsigned char *{name};"
    if re.search(
        r"\(\s*[A-Za-z_][A-Za-z0-9_\s]*\*\s*\)\s*\(\s*\b" + q + r"\b\s*[+-]",
        observed,
    ):
        return f"extern unsigned char *{name};"
    if re.search(r"\([A-Za-z_][A-Za-z0-9_\s*]*\)\s*\*\s*" + q + r"\b", observed):
        return f"extern unsigned long *{name};"
    pointer_cast = re.search(
        r"(?:\b" + q + r"\s*(?:==|!=|=)\s*\(([^()]*)\*\)|\(([^()]*)\*\)\s*\b" + q + r"\b)",
        observed,
    )
    if pointer_cast:
        cast_type = (pointer_cast.group(1) or pointer_cast.group(2) or "")
        if re.search(r"(?:char|byte|undefined1)\b", cast_type):
            return f"extern unsigned char *{name};"
        return f"extern unsigned long *{name};"
    if re.search(r"\*\s*\([^)]*\*\s*\)\s*\(\s*\b" + q + r"\b\s*[+-]", observed):
        return f"extern unsigned char *{name};"
    if pointer_locals is None:
        pointer_locals = re.findall(
            r"(?m)^\s*(?:const\s+)?[A-Za-z_]\w*(?:\s+[A-Za-z_]\w*)?\s*\*+\s*([A-Za-z_]\w*)\s*;",
            observed,
        )
    for local in pointer_locals:
        lq = re.escape(local)
        if (re.search(r"\b" + q + r"\s*=\s*" + lq + r"\b", observed) or
                re.search(r"\b" + lq + r"\s*=\s*" + q + r"\b", observed) or
                re.search(r"\b" + q + r"\s*(?:==|!=)\s*" + lq + r"\b", observed)):
            return f"extern unsigned long *{name};"
    if re.search(r"\b" + q + r"\s*=\s*(?:malloc|calloc|realloc|strdup|strndup|gettext|getenv)\s*\(", observed):
        return f"extern unsigned long *{name};"
    if (re.search(r"\b(?:strlen|strdup|strchr|strrchr)\s*\(\s*" + q + r"\b", observed) or
            re.search(r"\b(?:strcpy|strcat|strcmp)\s*\([^,;]+,\s*" + q + r"\b", observed)):
        return f"extern char *{name};"
    if re.search(
        r"\b" + q + r"\s*=\s*(?:FUN_[A-Za-z0-9_]+|[A-Za-z_]\w*_function)\b(?!\s*\()",
        observed,
    ):
        return f"extern long (*{name})();"
    if name.endswith(("_function", "_hook")):
        return f"extern long (*{name})();"
    # Constants wider than 32 bits prove the object participates in a
    # machine-word operation. This avoids the implicit four-byte global load.
    if re.search(r"\b" + q + r"\b[^;\n]*(?:0x[0-9a-fA-F]{9,}|[0-9]{11,})", observed):
        return f"extern unsigned long {name};"
    if re.search(r"(?:0x[0-9a-fA-F]{9,}|[0-9]{11,})[^;\n]*\b" + q + r"\b", observed):
        return f"extern unsigned long {name};"
    # An uncast global in floating arithmetic is a floating object; Ghidra
    # explicitly casts integer operands in the same expressions.
    if (re.search(r"\b" + q + r"\s*[*+/\-]\s*\(double\)", observed) or
            re.search(r"\(double\)[^;\n]*[*+/\-]\s*\b" + q + r"\b", observed)):
        return f"extern double {name};"
    for match in re.finditer(r"\*\s*\b" + q + r"\b", source):
        before = source[:match.start()].rstrip()
        if not before or before[-1] in "([=,!?:;{}":
            return f"extern unsigned char *{name};"
    uses = list(re.finditer(r"\b" + q + r"\b", source))
    if uses and all(source[max(0, m.start() - 2):m.start()].rstrip().endswith("&") for m in uses):
        return f"extern unsigned char {name};"
    return f"extern int {name};"


def repair(source: str, stderr: str, ctx) -> str | None:
    """Add storage declarations for globals gcc proves are undeclared."""
    try:
        names = list(dict.fromkeys(_UNDECLARED_RE.findall(stderr)))
        if not names:
            return None
        declarations = [_global_declaration(name, source) for name in names]
        return "\n".join(declarations) + "\n" + source
    except Exception:
        return None
